#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (NI, NJ, NK, NL, NM, DATA_TYPE, etc.)
#include "3mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D with the same values as the original C kernel.
 *
 * C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Halide layout (x-fastest, column index first):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(j, k) => B[k][j]   -> Buffer B(nj, nk)
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(l, m) => D[m][l]   -> Buffer D(nl, nm)
 *
 * This keeps the column index as the x-dimension (contiguous in memory).
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
    // A has shape [ni][nk] in C => A(k, i) in Halide
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(5 * ni);

    // B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
    // B has shape [nk][nj] in C => B(j, k) in Halide
    init_B(j, k) = cast<num_t>(((k * (j + 1) + 2) % nj)) / cast<int>(5 * nj);

    // C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    // Simple initialization schedule: row-major over the logical row (second) dim.
    init_A.reorder(k, i);
    init_B.reorder(j, k);
    init_C.reorder(m, j);
    init_D.reorder(l, m);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x = k / column, y = i / row)
    //           B[nk][nj] -> B(nj, nk)          (x = j, y = k)
    //           C[nj][nm] -> C(nm, nj)          (x = m, y = j)
    //           D[nm][nl] -> D(nl, nm)          (x = l, y = m)
    //           G[ni][nl] -> G(nl, ni)          (x = l, y = i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains (all use Halide's convention:
    //   x = column index, y = row index).
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over m for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over j for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i)  (x = j, y = i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{m=0..nm-1} C[j][m] * D[m][l]
    // Halide: F(l, j) (x = l, y = j); this is exactly F^T wrt C layout.
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{j=0..nj-1} E[i][j] * F[j][l]
    // Halide: G_func(l, i) (x = l, y = i); uses F as F_T[l][j]
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ---------------------------------------------------------------------
    // Scheduling: cache-friendly tiling, vectorization, and parallelism.
    //
    // We keep the pure functional definitions exactly as above and only
    // change the *schedule* to improve locality and throughput:
    //
    //   - E(j,i) = A(i,k) * B(k,j)
    //   - F(l,j) = C(j,m) * D(m,l)
    //   - G(l,i) = E(i,j) * F(j,l)
    //
    // The chosen schedule:
    //   - Tiles the output spaces of E, F, and G in (column, row).
    //   - Splits the reduction dimensions to work on cache-sized k/m/j blocks.
    //   - Vectorizes over the x-dimension (columns), which is contiguous.
    //   - Parallelizes over tiles of the row dimension (i or j), which
    //     are independent once the previous stages are computed.
    // ---------------------------------------------------------------------

    // Determine a reasonable SIMD width for the current host and element type.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes – chosen conservatively; they can be tuned for the machine.
    const int tile_i = 32;   // tile size in the row dimension (y)
    const int tile_j = 32;   // tile size in the column dimension for E (x = j)
    const int tile_l = 32;   // tile size in the column dimension for F,G (x = l)
    const int tile_k = 32;   // tile size in rAB (nk)
    const int tile_m = 32;   // tile size in rCD (nm)
    const int tile_r = 32;   // tile size in rEF (nj)

    // ----------------------
    // Stage 1: E = A * B
    // ----------------------
    //
    // Logical form:
    //   for i in [0,ni)
    //     for j in [0,nj)
    //       E(j,i) = sum_{k} A(k,i) * B(j,k)
    //
    // We block over (j,i) and k:
    //   - tiles of size tile_j x tile_i in (j,i)
    //   - chunks of size tile_k in the reduction rAB
    // and use an inner loop order:
    //   (tile rows) -> (tile cols) -> (k blocks) ->
    //     ii (rows inside tile) -> ki (reduction inside block) -> jj (cols inside tile)
    // which:
    //   - iterates jj (x = j) innermost for contiguous E and B
    //   - reuses A(k,i) across jj for each (i,k) pair
    //
    E.compute_root();

    // Optionally give the initialization pass a simple row-major schedule.
    E.reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    {
        Var j_outer("j_outer_E"), i_outer("i_outer_E");
        Var j_inner("j_inner_E"), i_inner("i_inner_E");
        RVar rAB_outer("rAB_outer"), rAB_inner("rAB_inner");

        E.update()
            // Tile the (j,i) space.
            .tile(j, i, j_outer, i_outer, j_inner, i_inner, tile_j, tile_i)
            // Split the reduction over k (rAB) into outer/inner pieces.
            .split(rAB, rAB_outer, rAB_inner, tile_k)
            // Reorder loops: innermost j_inner (vectorized), then rAB_inner, etc.
            // Order here is from innermost to outermost.
            .reorder(j_inner, rAB_inner, i_inner, rAB_outer, i_outer, j_outer)
            // SIMD over contiguous j_inner.
            .vectorize(j_inner, vec_width)
            // Parallelize across tiles in the row dimension (i_outer).
            .parallel(i_outer);
    }

    // ----------------------
    // Stage 2: F = C * D
    // ----------------------
    //
    // Logical form:
    //   for j in [0,nj)
    //     for l in [0,nl)
    //       F(l,j) = sum_{m} C(m,j) * D(l,m)
    //
    // This is a GEMM where:
    //   - rows are indexed by j  (second dim)
    //   - cols are indexed by l  (first dim)
    //   - reduction over m
    //
    // We block over (l,j) and m:
    //   - tiles of size tile_l x tile_j in (l,j)
    //   - chunks of size tile_m in rCD
    // and in the update we choose loop order:
    //   j_tile (rows) -> m_block -> l_tile
    // with l_inner innermost, giving contiguous accesses to F and D.
    //
    F.compute_root();

    // Simple initialization schedule for F: contiguous in x = l.
    F.reorder(l, j)
        .vectorize(l, vec_width)
        .parallel(j);

    {
        Var l_outer("l_outer_F"), j_outer_F("j_outer_F");
        Var l_inner("l_inner_F"), j_inner_F("j_inner_F");
        RVar rCD_outer("rCD_outer"), rCD_inner("rCD_inner");

        F.update()
            // Tile over (l,j).
            .tile(l, j, l_outer, j_outer_F, l_inner, j_inner_F, tile_l, tile_j)
            // Split the reduction over m.
            .split(rCD, rCD_outer, rCD_inner, tile_m)
            // Reorder so that l_inner (x = l) is innermost for contiguous F and D.
            .reorder(l_inner, rCD_inner, j_inner_F, rCD_outer, j_outer_F, l_outer)
            // SIMD over contiguous l.
            .vectorize(l_inner, vec_width)
            // Parallelize across tiles of j (rows of F).
            .parallel(j_outer_F);
    }

    // ----------------------
    // Stage 3: G = E * F
    // ----------------------
    //
    // Logical form:
    //   for i in [0,ni)
    //     for l in [0,nl)
    //       G(l,i) = sum_{j} E(j,i) * F(l,j)
    //
    // G has the same memory layout convention as E,F (x = column index).
    //
    // We again tile over (l,i) and split the reduction over j:
    //   - (l,i) into tiles of size tile_l x tile_i
    //   - rEF into blocks of size tile_r
    // and choose loop order so that l_inner is innermost to write G
    // contiguously, while the reduction over j proceeds in cache-sized blocks.
    //
    G_func.compute_root();

    // Initialization of G: simple row-major in (l,i).
    G_func.reorder(l, i)
        .vectorize(l, vec_width)
        .parallel(i);

    {
        Var l_outer_G("l_outer_G"), i_outer_G("i_outer_G");
        Var l_inner_G("l_inner_G"), i_inner_G("i_inner_G");
        RVar rEF_outer("rEF_outer"), rEF_inner("rEF_inner");

        G_func.update()
            .tile(l, i, l_outer_G, i_outer_G, l_inner_G, i_inner_G, tile_l, tile_i)
            .split(rEF, rEF_outer, rEF_inner, tile_r)
            // Inner-to-outer: l_inner (vectorized), rEF_inner, i_inner, rEF_outer, i_outer, l_outer.
            .reorder(l_inner_G, rEF_inner, i_inner_G, rEF_outer, i_outer_G, l_outer_G)
            .vectorize(l_inner_G, vec_width)
            .parallel(i_outer_G);
    }

    // Compile the kernel to machine code using the selected target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
