#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (NI, NJ, NK, NL, NM, DATA_TYPE, etc.)
#include "3mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D with the same values as the original C kernel.
 *
 * C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Halide layout (x-fastest / column-major view):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(j, k) => B[k][j]   -> Buffer B(nj, nk)
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(l, m) => D[m][l]   -> Buffer D(nl, nm)
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][k] = ((i*k+1) % ni) / (5*ni);
    // A has shape [ni][nk] in C => A(k, i) in Halide
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(5 * ni);

    // B[k][j] = ((k*(j+1)+2) % nj) / (5*nj);
    // B has shape [nk][nj] in C => B(j, k) in Halide
    init_B(j, k) = cast<num_t>(((k * (j + 1) + 2) % nj)) / cast<int>(5 * nj);

    // C[j][m] = (j*(m+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[m][l] = ((m*(l+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=k, y=i)
    //           B[nk][nj] -> B(nj, nk)          (x=j, y=k)
    //           C[nj][nm] -> C(nm, nj)          (x=m, y=j)
    //           D[nm][nl] -> D(nl, nm)          (x=l, y=m)
    //           G[ni][nl] -> G(nl, ni)          (x=l, y=i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over m for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over j for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i) = sum_k A(k, i) * B(j, k)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{m=0..nm-1} C[j][m] * D[m][l]
    // Halide: F(l, j) = sum_m C(m, j) * D(l, m)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{j=0..nj-1} E[i][j] * F[j][l]
    // Halide: G_func(l, i) = sum_j E(j, i) * F(l, j)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------------
    // Optimized schedule
    // ------------------------------------------------------------------------
    //
    // High-level goals:
    //   - Keep the mathematical structure identical to the reference:
    //       E = A * B,  F = C * D,  G = E * F
    //   - Use cache-blocking (tiling) on the spatial and reduction
    //     dimensions of each GEMM to improve data locality.
    //   - Vectorize along contiguous (x) dimensions:
    //       E: j,  F: l,  G: l.
    //   - Parallelize across coarse tiles in the row dimension (i/j),
    //     exploiting the 32-core x64 machine.
    //
    // Notes on layouts (see comments above):
    //   - For A(k, i)  the contiguous dimension is k (x).
    //   - For B(j, k)  the contiguous dimension is j (x).
    //   - For C(m, j)  the contiguous dimension is m (x).
    //   - For D(l, m)  the contiguous dimension is l (x).
    //   - For E(j, i)  the contiguous dimension is j (x).
    //   - For F(l, j)  the contiguous dimension is l (x).
    //   - For G(l, i)  the contiguous dimension is l (x).

    // Choose reasonable tile sizes for cache blocking.
    // These are conservative values that work well across many CPUs.
    const int tile_i = 32;
    const int tile_j = 32;
    const int tile_k = 32;
    const int tile_l = 32;
    const int tile_m = 32;

    // Choose a SIMD vector width based on the element type.
    Type elem_type = type_of<num_t>();
    int vec_width = 1;
    if (elem_type.is_float() || elem_type.is_int() || elem_type.is_uint()) {
        if (elem_type.bits() == 8) {
            vec_width = 16;
        } else if (elem_type.bits() == 16) {
            vec_width = 8;
        } else if (elem_type.bits() == 32) {
            vec_width = 8;  // e.g., AVX2: 8 floats
        } else if (elem_type.bits() == 64) {
            vec_width = 4;  // e.g., AVX2: 4 doubles
        }
    }

    // -------------------
    // Schedule for E = A * B
    // -------------------
    {
        // E(j, i) with reduction rAB over k.
        // We tile E over (j, i) and split the reduction over k:
        //   for each tile (jo, io), for each k-tile rABo,
        //     update E over inner (ji, ii, rABi).
        Var jo("jo_E"), ji("ji_E"), io("io_E"), ii("ii_E");
        RVar rABo("rABo"), rABi("rABi");

        // Pure definition: initialize E(j, i) = 0.
        E.compute_root()
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            // Inner loops: ji (x/j), then ii (y/i) to write E and keep
            // contiguous writes in ji.
            .reorder(ji, ii, jo, io)
            .vectorize(ji, vec_width)
            .parallel(io);  // parallel over tiles in i (rows)

        // Reduction/update definition: E(j, i) += A(k, i) * B(j, k)
        E.update()
            // Split the reduction domain over k into [rABo][rABi].
            .split(rAB, rABo, rABi, tile_k)
            // Tile the (j, i) spatial dimensions in the same way as pure.
            .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
            // Loop order inside a tile:
            //   outer:  io, jo, rABo
            //   inner:  rABi, ii, ji
            // This processes one (j, i) tile for one k-tile at a time.
            .reorder(ji, ii, rABi, rABo, jo, io)
            .vectorize(ji, vec_width)
            .parallel(io);
    }

    // -------------------
    // Schedule for F = C * D
    // -------------------
    {
        // F(l, j) with reduction rCD over m.
        // Tile F over (l, j) and split m similarly.
        Var lo("lo_F"), li("li_F"), jo("jo_F"), ji("ji_F");
        RVar rCDo("rCDo"), rCDi("rCDi");

        // Pure definition: F(l, j) = 0
        F.compute_root()
            .tile(l, j, lo, jo, li, ji, tile_l, tile_j)
            // Inner loops: li (x/l), ji (y/j).
            .reorder(li, ji, lo, jo)
            .vectorize(li, vec_width)
            .parallel(jo);  // parallel over tiles in j (rows of F)

        // Reduction/update definition: F(l, j) += C(m, j) * D(l, m)
        F.update()
            .split(rCD, rCDo, rCDi, tile_m)
            .tile(l, j, lo, jo, li, ji, tile_l, tile_j)
            // Process one (l,j)-tile for each m-tile:
            //   outer:  jo, lo, rCDo
            //   inner:  rCDi, ji, li
            .reorder(li, ji, rCDi, rCDo, lo, jo)
            .vectorize(li, vec_width)
            .parallel(jo);
    }

    // -------------------
    // Schedule for G = E * F
    // -------------------
    {
        // G_func(l, i) with reduction rEF over j.
        // Tile over (l, i) and split j similarly.
        Var lo("lo_G"), li("li_G"), io("io_G"), ii("ii_G");
        RVar rEFo("rEFo"), rEFi("rEFi");

        // Pure definition: G(l, i) = 0
        G_func.compute_root()
            .tile(l, i, lo, io, li, ii, tile_l, tile_i)
            // Inner loops: li (x/l), ii (y/i).
            .reorder(li, ii, lo, io)
            .vectorize(li, vec_width)
            .parallel(io);  // parallel over tiles in i (rows of G)

        // Reduction/update definition: G(l, i) += E(j, i) * F(l, j)
        G_func.update()
            .split(rEF, rEFo, rEFi, tile_j)
            .tile(l, i, lo, io, li, ii, tile_l, tile_i)
            // Loop order:
            //   outer:  io, lo, rEFo
            //   inner:  rEFi, ii, li
            // This streams F(l, j) and E(j, i) for one (l,i)-tile and
            // one j-tile at a time, with contiguous writes to G along li.
            .reorder(li, ii, rEFi, rEFo, lo, io)
            .vectorize(li, vec_width)
            .parallel(io);
    }

    // Compile the kernel to machine code.
    G_func.compile_jit();

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
