#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (NI, NJ, NK, NL, NM, DATA_TYPE, etc.)
#include "3mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D with the same values as the original C kernel.
 *
 * C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Halide layout (column-major / x-fastest):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(j, k) => B[k][j]   -> Buffer B(nj, nk)
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(l, m) => D[m][l]   -> Buffer D(nl, nm)
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
    // A has shape [ni][nk] in C => A(k, i) in Halide
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(5 * ni);

    // B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
    // B has shape [nk][nj] in C => B(j, k) in Halide
    init_B(j, k) = cast<num_t>(((k * (j + 1) + 2) % nj)) / cast<int>(5 * nj);

    // C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=k/col, y=i/row)
    //           B[nk][nj] -> B(nj, nk)          (x=j/col, y=k/row)
    //           C[nj][nm] -> C(nm, nj)          (x=m/col, y=j/row)
    //           D[nm][nl] -> D(nl, nm)          (x=l/col, y=m/row)
    //           G[ni][nl] -> G(nl, ni)          (x=l/col, y=i/row)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over k for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over k for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i) represents E[i][j]
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j) represents F[j][l]
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i) represents G[i][l]
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // --------------------------------------------------------------------
    // Optimized schedule
    //
    // We:
    //   * Keep the algorithm identical to the original PolyBench 3mm:
    //       E = A * B,   F = C * D,   G = E * F
    //   * Exploit the fact that the x-dimension of each Func is laid out
    //     contiguously in memory (Halide’s default), and:
    //       - E(j,i):  j is contiguous   (columns of E)
    //       - F(l,j):  l is contiguous   (columns of F)
    //       - G(l,i):  l is contiguous   (columns of G)
    //   * Parallelize across the outer row dimension for each stage.
    //   * Vectorize across the contiguous column dimension.
    //
    // This improves memory bandwidth utilization and makes good use of
    // the 32-core CPU and SIMD units, while preserving the original
    // reduction order in rAB/rCD/rEF, so floating-point results remain
    // bitwise identical to the simple triple-loop implementation.
    // --------------------------------------------------------------------

    // Choose a natural SIMD width for the current host and element type.
    Target target = get_host_target();
    const int vector_width = target.natural_vector_size(type_of<num_t>());

    // ---------- Stage 1: E = A * B ----------
    //
    // Logical loop structure we want:
    //   for i in [0, ni)      // rows of E/A  -- parallelized
    //     for j in [0, nj)    // cols of E/B  -- vectorized
    //       E(j,i) = 0;
    //       for k in [0, nk)  // rAB
    //         E(j,i) += A(k,i) * B(j,k);
    //
    // Memory access:
    //   - A(k,i): x=k is contiguous when rAB is innermost.
    //   - B(j,k): x=j is contiguous when j is innermost.
    //   - E(j,i): x=j is contiguous when j is innermost.
    //
    // We keep the reduction order over rAB unchanged and only reorder
    // the pure and update loops so that j is the innermost spatial
    // dimension, then parallelize over i and vectorize over j.

    E.compute_root();

    // Pure definition: initialize E(j,i) = 0.
    E.reorder(j, i)              // make j inner, i outer
     .parallel(i)                // parallelize rows of E
     .vectorize(j, vector_width); // SIMD across contiguous columns

    // Update definition (reduction over rAB): same ordering.
    E.update()
     .reorder(j, rAB, i)         // i outer, rAB middle, j innermost
     .parallel(i)                // rows of E are independent
     .vectorize(j, vector_width);

    // ---------- Stage 2: F = C * D ----------
    //
    // Logical loop structure:
    //   for j in [0, nj)      // rows of F/C  -- parallelized
    //     for l in [0, nl)    // cols of F/D  -- vectorized
    //       F(l,j) = 0;
    //       for m in [0, nm)  // rCD
    //         F(l,j) += C(m,j) * D(l,m);
    //
    // Memory access:
    //   - C(m,j): x=m contiguous when rCD is innermost.
    //   - D(l,m): x=l contiguous when l is innermost.
    //   - F(l,j): x=l contiguous when l is innermost.
    //
    // As with E, we keep reduction order over rCD unchanged, make l the
    // innermost spatial dimension, parallelize over j, and vectorize l.

    F.compute_root();

    // Pure definition: initialize F(l,j) = 0.
    F.reorder(l, j)              // make l inner, j outer
     .parallel(j)                // parallelize rows of F
     .vectorize(l, vector_width);

    // Update definition (reduction over rCD).
    F.update()
     .reorder(l, rCD, j)         // j outer, rCD middle, l innermost
     .parallel(j)                // rows of F are independent
     .vectorize(l, vector_width);

    // ---------- Stage 3: G = E * F ----------
    //
    // Logical loop structure:
    //   for i in [0, ni)      // rows of G/E  -- parallelized
    //     for l in [0, nl)    // cols of G/F  -- vectorized
    //       G(l,i) = 0;
    //       for j in [0, nj)  // rEF
    //         G(l,i) += E(j,i) * F(l,j);
    //
    // Memory access:
    //   - E(j,i): x=j contiguous when rEF is innermost.
    //   - F(l,j): x=l contiguous when l is innermost.
    //   - G(l,i): x=l contiguous when l is innermost.
    //
    // We keep the reduction over rEF in the same order and make l the
    // innermost spatial dimension, parallelizing over i and vectorizing l.

    G_func.compute_root();

    // Pure definition: initialize G(l,i) = 0.
    G_func.reorder(l, i)               // make l inner, i outer
          .parallel(i)                 // parallelize rows of G
          .vectorize(l, vector_width);

    // Update definition (reduction over rEF).
    G_func.update()
          .reorder(l, rEF, i)          // i outer, rEF middle, l innermost
          .parallel(i)                 // rows of G are independent
          .vectorize(l, vector_width);

    // Compile the kernel to machine code.
    G_func.compile_jit();

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
