#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions
#include "defines.hpp"

// include benchmark-specific definitions (NI, NJ, NK, NL, NM, DATA_TYPE, etc.)
#include "3mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D with the same values as the original C kernel.
 *
 * C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Halide layout (column-major / x-fastest):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(j, k) => B[k][j]   -> Buffer B(nj, nk)   (B stored transposed: B_T[j][k])
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(l, m) => D[m][l]   -> Buffer D(nl, nm)   (D stored transposed: D_T[l][m])
 *
 * These layouts match the conceptual model 3mm-05: we store B and D in
 * transposed form so that the reduction dimensions (k for A*B, m for C*D)
 * are contiguous in memory for both inputs, which improves locality.
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
    // A has shape [ni][nk] in C => A(k, i) in Halide
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(5 * ni);

    // B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
    // B has shape [nk][nj] in C => B(j, k) in Halide (B_T[j][k])
    init_B(j, k) = cast<num_t>(((k * (j + 1) + 2) % nj)) / cast<int>(5 * nj);

    // C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
    // C has shape [nj][nm] in C => C(m, j) in Halide
    init_C(m, j) = cast<num_t>(((j * (m + 3)) % nl)) / cast<int>(5 * nl);

    // D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
    // D has shape [nm][nl] in C => D(l, m) in Halide (D_T[l][m])
    init_D(l, m) = cast<num_t>(((m * (l + 2) + 2) % nk)) / cast<int>(5 * nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(nk, ni)  (x=k/col, y=i/row)
    //           B[nk][nj] -> B(nj, nk)          (x=j,     y=k)  (B_T)
    //           C[nj][nm] -> C(nm, nj)          (x=m,     y=j)
    //           D[nm][nl] -> D(nl, nm)          (x=l,     y=m)  (D_T)
    //           G[ni][nl] -> G(nl, ni)          (x=l,     y=i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);  // final result

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Create ImageParams for the input matrices so that the Halide
    // pipeline can be compiled independently of specific Buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom rAB(0, nk, "rAB");  // reduction over k for E = A * B
    RDom rCD(0, nm, "rCD");  // reduction over m for F = C * D
    RDom rEF(0, nj, "rEF");  // reduction over j for G = E * F

    // Define Funcs for the three matrix multiplications.
    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Our layout: A(k, i) == A[i][k], B(j, k) == B[k][j], E(j, i) == E[i][j]
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{m=0..nm-1} C[j][m] * D[m][l]
    // Our layout: C(m, j) == C[j][m], D(l, m) == D[m][l], F(l, j) == F_T[l][j]
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{j=0..nj-1} E[i][j] * F[j][l]
    // Our layout: G_func(l, i) == G[i][l], E(j, i) == E[i][j], F(l, j) == F_T[l][j]
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------
    // Optimized schedule
    // ------------------------------------------------------------------
    // Strategy:
    //   - Materialize E and F at root (as in the original code) but with
    //     cache-friendly, tiled loop nests.
    //   - Use separate schedules for pure and update definitions.
    //   - Tile the output spatial dimensions to improve locality.
    //   - Vectorize along the x dimension (j or l), which is contiguous
    //     in memory for our layouts.
    //   - Parallelize across tiles of the outer (row-like) dimension.
    //
    // Note: We do not change the mathematical computation, only the
    //       evaluation order and loop structure.

    // Get a Target so we can choose a reasonable SIMD width.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    // Choose tile sizes. 32x32 tiles work well for a wide range of sizes
    // and fit comfortably into L1/L2 for double or float.
    const int tile_i = 32;  // tiles over rows (i-like dimension)
    const int tile_j = 32;  // tiles over columns (j-like dimension)
    const int tile_l = 32;  // tiles over columns (l-like dimension)

    // -------------------------------
    // Schedule for E = A * B
    // E(j, i) = sum_k A(k, i) * B(j, k)
    // -------------------------------
    {
        // Tile the (j, i) domain. We treat j as x (contiguous) and i as y.
        Var j_outer_E("j_outer_E"), i_outer_E("i_outer_E");
        Var j_inner_E("j_inner_E"), i_inner_E("i_inner_E");

        E.compute_root();

        // Pure definition: zero initialization of E.
        // Loop order inside tiles: i_outer, j_outer, i_inner, j_inner
        // with j_inner innermost for contiguous writes.
        E.tile(j, i, j_outer_E, i_outer_E, j_inner_E, i_inner_E,
               tile_j, tile_i)
         .reorder(j_inner_E, i_inner_E, j_outer_E, i_outer_E)
         .vectorize(j_inner_E, vec_width)
         .parallel(i_outer_E);

        // Update definition (reduction over rAB).
        // For each tile, we iterate over the full reduction domain.
        E.update()
         .tile(j, i, j_outer_E, i_outer_E, j_inner_E, i_inner_E,
               tile_j, tile_i)
         // Innermost: j_inner_E for contiguous B/E, then i_inner_E,
         // then reduction rAB, then tile indices.
         .reorder(j_inner_E, i_inner_E, rAB, j_outer_E, i_outer_E)
         .vectorize(j_inner_E, vec_width)
         .parallel(i_outer_E);
    }

    // -------------------------------
    // Schedule for F = C * D
    // F(l, j) = sum_m C(m, j) * D(l, m)
    // -------------------------------
    {
        // Tile the (l, j) domain. l is x (contiguous), j is y.
        Var l_outer_F("l_outer_F"), j_outer_F("j_outer_F");
        Var l_inner_F("l_inner_F"), j_inner_F("j_inner_F");

        F.compute_root();

        // Pure definition: zero initialization of F.
        F.tile(l, j, l_outer_F, j_outer_F, l_inner_F, j_inner_F,
               tile_l, tile_j)
         .reorder(l_inner_F, j_inner_F, l_outer_F, j_outer_F)
         .vectorize(l_inner_F, vec_width)
         .parallel(j_outer_F);

        // Update definition (reduction over rCD).
        F.update()
         .tile(l, j, l_outer_F, j_outer_F, l_inner_F, j_inner_F,
               tile_l, tile_j)
         // Innermost: l_inner_F for contiguous D/F, then j_inner_F,
         // then reduction rCD, then tile indices.
         .reorder(l_inner_F, j_inner_F, rCD, l_outer_F, j_outer_F)
         .vectorize(l_inner_F, vec_width)
         .parallel(j_outer_F);
    }

    // -------------------------------
    // Schedule for G = E * F
    // G_func(l, i) = sum_j E(j, i) * F(l, j)
    // -------------------------------
    {
        // Tile the (l, i) domain. l is x (contiguous), i is y.
        Var l_outer_G("l_outer_G"), i_outer_G("i_outer_G");
        Var l_inner_G("l_inner_G"), i_inner_G("i_inner_G");

        G_func.compute_root();

        // Pure definition: zero initialization of G.
        G_func.tile(l, i, l_outer_G, i_outer_G, l_inner_G, i_inner_G,
                    tile_l, tile_i)
              .reorder(l_inner_G, i_inner_G, l_outer_G, i_outer_G)
              .vectorize(l_inner_G, vec_width)
              .parallel(i_outer_G);

        // Update definition (reduction over rEF).
        G_func.update()
              .tile(l, i, l_outer_G, i_outer_G, l_inner_G, i_inner_G,
                    tile_l, tile_i)
              // Innermost: l_inner_G for contiguous G and F, then i_inner_G,
              // then reduction rEF, then tile indices.
              .reorder(l_inner_G, i_inner_G, rEF, l_outer_G, i_outer_G)
              .vectorize(l_inner_G, vec_width)
              .parallel(i_outer_G);
    }

    // Compile the kernel to machine code for the chosen target.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
